import React, { useState, useEffect } from 'react';

export function DemoComponent() {
  const [data, setData] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let active = true;
    setLoading(true);
    // Simulating verified async operation for Custom Hooks & State Composition
    const timer = setTimeout(() => {
      if (active) {
        setData('Custom Hooks & State Composition loaded successfully');
        setLoading(false);
      }
    }, 100);
    return () => { active = false; clearTimeout(timer); };
  }, []);

  return (
    <div className="p-4 rounded-xl border bg-card">
      <h3 className="font-bold text-primary">Custom Hooks & State Composition</h3>
      {loading ? <p>Loading...</p> : <p className="text-sm">{data}</p>}
    </div>
  );
}

